if mode == "deepseek_intent" {
    try! NativeWorkbench.save(["kind0":"ChatGPT","kind1":"DeepSeek","url0":base.absoluteString,"url1":base.absoluteString],at:prefs.appendingPathComponent("paired-workbench.json"))
    let work=IntegratedWorkbench(preferences:prefs,resources:resources,translate:{$0},openProjects:{fatalError("no business action")})
    work.dialogue=PairedDialogue(id:"TEST-INTENT",providers:["ChatGPT","DeepSeek"],conversations:[base.absoluteString,base.absoluteString],roles:["",""],firstText:"TEST ONLY",maxExchanges:0,duration:0,createdAt:Date().timeIntervalSince1970,state:"running",untilStopped:true,checkboxMode:true,firstSource:0,autoSendEnabled:true)
    precondition(work.saveDialogue() && work.dialogue!.valid)
    work.pauseDialogue("Reply observation needs attention: GENERATION_STATE_UNCONFIRMED")
    precondition(work.dialogue?.state=="paused" && work.dialogue?.automaticIntent==true)
    precondition(work.webPanes.values.allSatisfy(\.automaticReplyEnabled),"safety pause must not impersonate user cancellation")
    precondition(work.webTransfers.isEmpty && work.dialogue?.sentCount==0,"state projection cannot dispatch")
    let persisted=try! JSONDecoder().decode(PairedDialogue.self,from:Data(contentsOf:prefs.appendingPathComponent("paired-dialogue.json")))
    precondition(persisted.automaticIntent && persisted.state=="paused")
    let restored=IntegratedWorkbench(preferences:prefs,resources:resources,translate:{$0},openProjects:{fatalError("no business action")})
    precondition(restored.dialogue?.id=="TEST-INTENT" && restored.dialogue?.automaticIntent==false,"restart preserves receipts but does not resume opt-in")
    work.stopDialogueFromPane(1,source:base)
    precondition(work.dialogue?.state=="stopped" && work.dialogue?.automaticIntent==false)
    precondition(work.webPanes.values.allSatisfy{!$0.automaticReplyEnabled})
    work.pauseDialogue("late failure")
    precondition(work.dialogue?.state=="stopped" && work.dialogue?.automaticIntent==false,"late callbacks cannot restore intent")
    print("SIMULATED_NATIVE_INTENT_PAUSE_STOP_RESTART_NO_DISPATCH_PASS");exit(0)
}
